/**
 * CSS selector generation for the element picker. Produces several
 * candidates, from the most specific (a unique path) to broader ones (a class
 * combination), skipping auto-generated ids and class names that would change
 * on the next page load.
 */

/** Ids/classes like `css-1x2y3z`, `sc-AbCdE`, `a8f3e9c1` are generated by build tools. */
export function looksGenerated(token: string): boolean {
  if (token.length > 40) return true;
  if (/\d{4,}/.test(token)) return true;
  if (/^(css|sc|jsx|emotion|styled)-/i.test(token)) return true;
  if (/^[a-f0-9]{6,}$/i.test(token)) return true;
  // Mixed-case gibberish with digits: `xH3kQ9`
  const digits = (token.match(/\d/g) ?? []).length;
  const uppers = (token.match(/[A-Z]/g) ?? []).length;
  return token.length >= 6 && digits >= 2 && uppers >= 2;
}

const esc = (s: string) => (typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(s) : s.replace(/([^\w-])/g, '\\$1'));

function stableClasses(el: Element): string[] {
  return Array.from(el.classList).filter((c) => c !== '' && !looksGenerated(c));
}

function countMatches(selector: string, root: ParentNode): number {
  try {
    return root.querySelectorAll(selector).length;
  } catch {
    return Infinity;
  }
}

/** One path segment for `el`: `tag#id`, `tag.cls`, with `:nth-of-type` when needed. */
function segment(el: Element): string {
  const tag = el.localName;
  if (el.id && !looksGenerated(el.id)) return `${tag}#${esc(el.id)}`;
  let seg =
    tag +
    stableClasses(el)
      .slice(0, 3)
      .map((c) => `.${esc(c)}`)
      .join('');
  const parent = el.parentElement;
  if (parent) {
    const siblings = Array.from(parent.children).filter((s) => s.localName === tag);
    if (siblings.length > 1 && countMatches(`:scope > ${seg}`, parent) > 1) {
      seg += `:nth-of-type(${siblings.indexOf(el) + 1})`;
    }
  }
  return seg;
}

/** A selector that matches exactly `el` (in the current document). */
export function uniquePath(el: Element, root: Document = el.ownerDocument): string {
  const parts: string[] = [];
  for (let cur: Element | null = el; cur && cur !== root.documentElement; cur = cur.parentElement) {
    parts.unshift(segment(cur));
    const selector = parts.join(' > ');
    if (cur.id && !looksGenerated(cur.id)) {
      if (countMatches(selector, root) === 1) return selector;
    } else if (parts.length >= 2 && countMatches(selector, root) === 1) {
      return selector;
    }
  }
  return parts.join(' > ');
}

function urlSelector(el: Element): string | null {
  const attr =
    el.localName === 'a' ? 'href' : ['img', 'iframe', 'video', 'source', 'embed'].includes(el.localName) ? 'src' : null;
  if (!attr) return null;
  const value = el.getAttribute(attr);
  if (!value) return null;
  try {
    const url = new URL(value, el.ownerDocument.baseURI);
    if (!/^https?:$/.test(url.protocol)) return null;
    const file = url.pathname.split('/').filter(Boolean).pop();
    const needle = file && file.length >= 4 && !looksGenerated(file) ? `${url.hostname}/` : url.hostname;
    return `${el.localName}[${attr}*="${needle.replace(/"/g, '\\"')}"]`;
  } catch {
    return null;
  }
}

export interface Candidate {
  selector: string;
  count: number;
}

/** Candidate selectors for `el`, most specific first, each with its match count. */
export function candidateSelectors(el: Element): Candidate[] {
  const root = el.ownerDocument;
  const out = new Map<string, number>();
  const add = (s: string | null) => {
    if (!s || out.has(s)) return;
    const n = countMatches(s, root);
    if (n > 0 && n !== Infinity) out.set(s, n);
  };

  add(uniquePath(el, root));
  if (el.id && !looksGenerated(el.id)) add(`#${esc(el.id)}`);
  const classes = stableClasses(el);
  if (classes.length > 0) {
    add(`${el.localName}${classes.map((c) => `.${esc(c)}`).join('')}`);
    for (const c of classes) add(`.${esc(c)}`);
  }
  add(urlSelector(el));
  // A few ancestors, for when the element is a small piece of an ad block.
  let parent = el.parentElement;
  for (let i = 0; parent && i < 3 && parent !== root.body; i++, parent = parent.parentElement) {
    if (parent.id && !looksGenerated(parent.id)) add(`#${esc(parent.id)}`);
    const pc = stableClasses(parent);
    if (pc.length > 0) add(`${parent.localName}.${pc.map(esc).join('.')}`);
  }
  return [...out].map(([selector, count]) => ({ selector, count })).sort((a, b) => a.count - b.count);
}
